  ($id$potpot-m-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$medium$diff$, $prompt$Simplifica: $3(x^2)^4$$prompt$, $json$[{"latex":"3x^8","correct":true},{"latex":"3x^6","correct":false},{"latex":"3x^{16}","correct":false},{"latex":"12x^8","correct":false}]$json$::jsonb, $exp$El coeficiente 3 queda fuera: $3 \cdot x^{2 \cdot 4} = 3x^8$. El 4 no multiplica al 3.$exp$),
  ($id$potpot-m-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$medium$diff$, $prompt$Simplifica y evalúa: $(2^2)^3$$prompt$, $json$[{"latex":"64","correct":true},{"latex":"32","correct":false},{"latex":"12","correct":false},{"latex":"128","correct":false}]$json$::jsonb, $exp$$(2^2)^3 = 2^{2 \cdot 3} = 2^6 = 64$.$exp$),
  ($id$potpot-m-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$medium$diff$, $prompt$Simplifica: $(m^3)^4$$prompt$, $json$[{"latex":"m^{12}","correct":true},{"latex":"m^7","correct":false},{"latex":"m^{64}","correct":false},{"latex":"m^3","correct":false}]$json$::jsonb, $exp$Se multiplican los exponentes: $3 \cdot 4 = 12$, por lo que $m^{12}$.$exp$),
  ($id$potpot-m-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$medium$diff$, $prompt$Simplifica: $-(x^2)^3$$prompt$, $json$[{"latex":"-x^6","correct":true},{"latex":"x^6","correct":false},{"latex":"-x^5","correct":false},{"latex":"x^5","correct":false}]$json$::jsonb, $exp$$(x^2)^3 = x^6$ y el signo negativo de afuera se conserva: $-x^6$.$exp$),
  ($id$potpot-m-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$medium$diff$, $prompt$Simplifica: $(3^2)^4$$prompt$, $json$[{"latex":"3^8","correct":true},{"latex":"3^6","correct":false},{"latex":"3^{16}","correct":false},{"latex":"3^2","correct":false}]$json$::jsonb, $exp$Se multiplican los exponentes: $2 \cdot 4 = 8$, por lo que $3^8$.$exp$),
  ($id$potpot-h-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$hard$diff$, $prompt$Simplifica: $((x^2)^3)^2$$prompt$, $json$[{"latex":"x^{12}","correct":true},{"latex":"x^7","correct":false},{"latex":"x^{36}","correct":false},{"latex":"x^{24}","correct":false}]$json$::jsonb, $exp$De adentro hacia afuera: $(x^2)^3 = x^6$, luego $(x^6)^2 = x^{12}$. O multiplica $2 \cdot 3 \cdot 2 = 12$.$exp$),
  ($id$potpot-h-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$hard$diff$, $prompt$Si $(2^x)^2 = 64$, ¿cuál es el valor de $x$?$prompt$, $json$[{"latex":"3","correct":true},{"latex":"6","correct":false},{"latex":"2","correct":false},{"latex":"4","correct":false}]$json$::jsonb, $exp$$(2^x)^2 = 2^{2x}$. Como $64 = 2^6$, entonces $2x = 6$, luego $x = 3$.$exp$),
  ($id$potpot-h-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$hard$diff$, $prompt$Si $(x^3)^n = x^{15}$, ¿cuál es el valor de $n$?$prompt$, $json$[{"latex":"5","correct":true},{"latex":"3","correct":false},{"latex":"15","correct":false},{"latex":"12","correct":false}]$json$::jsonb, $exp$$(x^3)^n = x^{3n}$. Igualamos: $3n = 15$, por lo que $n = 5$.$exp$),
  ($id$potpot-h-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$hard$diff$, $prompt$Simplifica: $(a^2)^3 \cdot (a^2)^2$$prompt$, $json$[{"latex":"a^{10}","correct":true},{"latex":"a^7","correct":false},{"latex":"a^{24}","correct":false},{"latex":"a^{12}","correct":false}]$json$::jsonb, $exp$$(a^2)^3 = a^6$ y $(a^2)^2 = a^4$. Luego $a^6 \cdot a^4 = a^{6+4} = a^{10}$.$exp$),
  ($id$potpot-h-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-potencia$law$, $diff$hard$diff$, $prompt$Simplifica y evalúa: $(10^2)^2$$prompt$, $json$[{"latex":"10000","correct":true},{"latex":"100","correct":false},{"latex":"40","correct":false},{"latex":"1000","correct":false}]$json$::jsonb, $exp$$(10^2)^2 = 10^{2 \cdot 2} = 10^4 = 10000$.$exp$),
  ($id$potpro-f-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$easy$diff$, $prompt$Simplifica: $(ab)^2$$prompt$, $json$[{"latex":"a^2 b^2","correct":true},{"latex":"a^2 b","correct":false},{"latex":"ab^2","correct":false},{"latex":"a^2 + b^2","correct":false}]$json$::jsonb, $exp$El exponente se reparte a cada factor: $(ab)^2 = a^2 b^2$. No se distribuye sobre una suma.$exp$),
  ($id$potpro-f-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$easy$diff$, $prompt$Simplifica: $(xy)^3$$prompt$, $json$[{"latex":"x^3 y^3","correct":true},{"latex":"x^3 y","correct":false},{"latex":"xy^3","correct":false},{"latex":"x^3 + y^3","correct":false}]$json$::jsonb, $exp$El exponente se reparte: $(xy)^3 = x^3 y^3$.$exp$)
INSERT INTO public.questions (id, section_id, subtema_id, law_id, difficulty, prompt, options, explanation)
VALUES
  ($id$potpro-f-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$easy$diff$, $prompt$Simplifica: $(2x)^2$$prompt$, $json$[{"latex":"4x^2","correct":true},{"latex":"2x^2","correct":false},{"latex":"4x","correct":false},{"latex":"2x","correct":false}]$json$::jsonb, $exp$Eleva ambos factores al cuadrado: $2^2 \cdot x^2 = 4x^2$.$exp$),
  ($id$potpro-f-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$easy$diff$, $prompt$Simplifica: $(3y)^2$$prompt$, $json$[{"latex":"9y^2","correct":true},{"latex":"6y^2","correct":false},{"latex":"3y^2","correct":false},{"latex":"9y","correct":false}]$json$::jsonb, $exp$$3^2 \cdot y^2 = 9y^2$. El 3 también se eleva al cuadrado.$exp$),
  ($id$potpro-f-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$easy$diff$, $prompt$Simplifica: $(mn)^4$$prompt$, $json$[{"latex":"m^4 n^4","correct":true},{"latex":"m^4 n","correct":false},{"latex":"mn^4","correct":false},{"latex":"4mn","correct":false}]$json$::jsonb, $exp$El exponente se reparte: $(mn)^4 = m^4 n^4$.$exp$),
  ($id$potpro-m-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$medium$diff$, $prompt$Simplifica: $(2xy)^3$$prompt$, $json$[{"latex":"8x^3 y^3","correct":true},{"latex":"6x^3 y^3","correct":false},{"latex":"8x^3 y","correct":false},{"latex":"2x^3 y^3","correct":false}]$json$::jsonb, $exp$$2^3 = 8$, $x^3$ y $y^3$. Resultado: $8x^3 y^3$. No se multiplica el 2 por 3.$exp$),
  ($id$potpro-m-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$medium$diff$, $prompt$Simplifica: $(-2x)^2$$prompt$, $json$[{"latex":"4x^2","correct":true},{"latex":"-4x^2","correct":false},{"latex":"2x^2","correct":false},{"latex":"-2x^2","correct":false}]$json$::jsonb, $exp$$(-2)^2 = 4$ (el signo negativo se anula al elevar al cuadrado) y $x^2$: $4x^2$.$exp$),
  ($id$potpro-m-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$medium$diff$, $prompt$Simplifica: $(3a^2 b)^2$$prompt$, $json$[{"latex":"9a^4 b^2","correct":true},{"latex":"6a^4 b^2","correct":false},{"latex":"9a^4 b","correct":false},{"latex":"3a^4 b^2","correct":false}]$json$::jsonb, $exp$$3^2 = 9$, $(a^2)^2 = a^4$ y $b^2$. Resultado: $9a^4 b^2$.$exp$),
  ($id$potpro-m-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$medium$diff$, $prompt$Simplifica: $(5xy^2)^2$$prompt$, $json$[{"latex":"25x^2 y^4","correct":true},{"latex":"10x^2 y^4","correct":false},{"latex":"25x^2 y^2","correct":false},{"latex":"25x y^4","correct":false}]$json$::jsonb, $exp$$5^2 = 25$, $x^2$ y $(y^2)^2 = y^4$. Resultado: $25x^2 y^4$.$exp$),
  ($id$potpro-m-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$medium$diff$, $prompt$Simplifica: $(-3x^2)^2$$prompt$, $json$[{"latex":"9x^4","correct":true},{"latex":"-9x^4","correct":false},{"latex":"6x^4","correct":false},{"latex":"-6x^4","correct":false}]$json$::jsonb, $exp$$(-3)^2 = 9$ y $(x^2)^2 = x^4$. Resultado: $9x^4$.$exp$),
  ($id$potpro-h-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$hard$diff$, $prompt$Simplifica: $(2x^2 y^3)^3$$prompt$, $json$[{"latex":"8x^6 y^9","correct":true},{"latex":"6x^6 y^9","correct":false},{"latex":"8x^5 y^6","correct":false},{"latex":"6x^5 y^6","correct":false}]$json$::jsonb, $exp$$2^3 = 8$, $(x^2)^3 = x^6$ y $(y^3)^3 = y^9$. Resultado: $8x^6 y^9$.$exp$),
  ($id$potpro-h-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$hard$diff$, $prompt$Simplifica: $(-2x^3 y)^3$$prompt$, $json$[{"latex":"-8x^9 y^3","correct":true},{"latex":"8x^9 y^3","correct":false},{"latex":"-6x^9 y^3","correct":false},{"latex":"-8x^6 y^3","correct":false}]$json$::jsonb, $exp$$(-2)^3 = -8$ (exponente impar conserva el signo), $(x^3)^3 = x^9$ y $y^3$. Resultado: $-8x^9 y^3$.$exp$),
  ($id$potpro-h-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$hard$diff$, $prompt$Simplifica y evalúa: $(2 \cdot 3)^2$$prompt$, $json$[{"latex":"36","correct":true},{"latex":"12","correct":false},{"latex":"18","correct":false},{"latex":"72","correct":false}]$json$::jsonb, $exp$$(2 \cdot 3)^2 = 2^2 \cdot 3^2 = 4 \cdot 9 = 36$.$exp$),
  ($id$potpro-h-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$hard$diff$, $prompt$Si $(2x)^n = 8x^3$, ¿cuál es el valor de $n$?$prompt$, $json$[{"latex":"3","correct":true},{"latex":"2","correct":false},{"latex":"4","correct":false},{"latex":"8","correct":false}]$json$::jsonb, $exp$$(2x)^3 = 2^3 x^3 = 8x^3$, por lo que $n = 3$.$exp$),
  ($id$potpro-h-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$potencia-producto$law$, $diff$hard$diff$, $prompt$Simplifica: $(ab^2 c)^2$$prompt$, $json$[{"latex":"a^2 b^4 c^2","correct":true},{"latex":"a^2 b^4 c","correct":false},{"latex":"a^2 b^2 c^2","correct":false},{"latex":"ab^4 c^2","correct":false}]$json$::jsonb, $exp$Se reparte el exponente a todos: $a^2$, $(b^2)^2 = b^4$ y $c^2$. Resultado: $a^2 b^4 c^2$.$exp$),
  ($id$exp0-f-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$easy$diff$, $prompt$Simplifica: $5^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"0","correct":false},{"latex":"5","correct":false},{"latex":"-5","correct":false}]$json$::jsonb, $exp$Todo número distinto de cero elevado a la 0 es 1: $5^0 = 1$.$exp$),
  ($id$exp0-f-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$easy$diff$, $prompt$Simplifica: $x^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"0","correct":false},{"latex":"x","correct":false},{"latex":"-x","correct":false}]$json$::jsonb, $exp$Para cualquier $x \neq 0$: $x^0 = 1$.$exp$),
  ($id$exp0-f-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$easy$diff$, $prompt$Simplifica: $(-3)^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"-1","correct":false},{"latex":"0","correct":false},{"latex":"3","correct":false}]$json$::jsonb, $exp$La base completa (con su signo) elevada a la 0 es 1: $(-3)^0 = 1$.$exp$),
  ($id$exp0-f-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$easy$diff$, $prompt$Simplifica: $(2x)^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"0","correct":false},{"latex":"2x","correct":false},{"latex":"-1","correct":false}]$json$::jsonb, $exp$Toda la expresión $(2x)$ elevada a la 0 es 1 (siempre que $2x \neq 0$).$exp$),
  ($id$exp0-f-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$easy$diff$, $prompt$Simplifica: $100^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"0","correct":false},{"latex":"100","correct":false},{"latex":"10","correct":false}]$json$::jsonb, $exp$Sin importar el tamaño del número: $100^0 = 1$.$exp$),
  ($id$exp0-m-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$medium$diff$, $prompt$Simplifica: $3x^0$$prompt$, $json$[{"latex":"3","correct":true},{"latex":"0","correct":false},{"latex":"3x","correct":false},{"latex":"1","correct":false}]$json$::jsonb, $exp$Solo la $x$ está elevada a la 0: $3 \cdot x^0 = 3 \cdot 1 = 3$.$exp$),
  ($id$exp0-m-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$medium$diff$, $prompt$Simplifica: $(5^2)^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"5","correct":false},{"latex":"25","correct":false},{"latex":"0","correct":false}]$json$::jsonb, $exp$Cualquier potencia elevada a la 0 es 1: $(5^2)^0 = 1$.$exp$),
  ($id$exp0-m-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$medium$diff$, $prompt$Simplifica: $x^0 + y^0$$prompt$, $json$[{"latex":"2","correct":true},{"latex":"0","correct":false},{"latex":"x + y","correct":false},{"latex":"1","correct":false}]$json$::jsonb, $exp$$x^0 = 1$ y $y^0 = 1$, por lo que $x^0 + y^0 = 1 + 1 = 2$.$exp$),
  ($id$exp0-m-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$medium$diff$, $prompt$Simplifica: $(ab)^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"0","correct":false},{"latex":"ab","correct":false},{"latex":"a + b","correct":false}]$json$::jsonb, $exp$Toda la expresión $(ab)$ elevada a la 0 es 1 (con $a,b \neq 0$).$exp$),
  ($id$exp0-m-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$medium$diff$, $prompt$Simplifica: $-(4)^0$$prompt$, $json$[{"latex":"-1","correct":true},{"latex":"1","correct":false},{"latex":"0","correct":false},{"latex":"-4","correct":false}]$json$::jsonb, $exp$Primero $4^0 = 1$ y luego se aplica el signo de afuera: $-(4^0) = -1$.$exp$),
  ($id$exp0-h-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$hard$diff$, $prompt$Simplifica: $7x^0 y^0$$prompt$, $json$[{"latex":"7","correct":true},{"latex":"0","correct":false},{"latex":"7xy","correct":false},{"latex":"1","correct":false}]$json$::jsonb, $exp$$x^0 = 1$ y $y^0 = 1$, así que $7 \cdot 1 \cdot 1 = 7$.$exp$),
  ($id$exp0-h-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$hard$diff$, $prompt$Simplifica: $(x^2 y)^0 \cdot 3$$prompt$, $json$[{"latex":"3","correct":true},{"latex":"0","correct":false},{"latex":"3x^2 y","correct":false},{"latex":"1","correct":false}]$json$::jsonb, $exp$$(x^2 y)^0 = 1$, por lo que $1 \cdot 3 = 3$.$exp$),
  ($id$exp0-h-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$hard$diff$, $prompt$Si $2^0 + 3^0 + 4^0 = n$, ¿cuál es el valor de $n$?$prompt$, $json$[{"latex":"3","correct":true},{"latex":"0","correct":false},{"latex":"9","correct":false},{"latex":"1","correct":false}]$json$::jsonb, $exp$$2^0 = 3^0 = 4^0 = 1$, por lo que $1 + 1 + 1 = 3$.$exp$),
  ($id$exp0-h-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$hard$diff$, $prompt$Simplifica: $\frac{5^3}{5^3}$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"5","correct":false},{"latex":"0","correct":false},{"latex":"25","correct":false}]$json$::jsonb, $exp$$\frac{5^3}{5^3} = 5^{3-3} = 5^0 = 1$. Todo número dividido entre sí mismo es 1.$exp$),
  ($id$exp0-h-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-cero$law$, $diff$hard$diff$, $prompt$Simplifica: $(2x^2 - y)^0$$prompt$, $json$[{"latex":"1","correct":true},{"latex":"0","correct":false},{"latex":"2x^2 - y","correct":false},{"latex":"-1","correct":false}]$json$::jsonb, $exp$Toda expresión distinta de cero elevada a la 0 es 1, sin importar lo compleja que sea.$exp$),
  ($id$expneg-f-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$easy$diff$, $prompt$Simplifica: $2^{-3}$$prompt$, $json$[{"latex":"\\frac{1}{8}","correct":true},{"latex":"-8","correct":false},{"latex":"-6","correct":false},{"latex":"8","correct":false}]$json$::jsonb, $exp$$2^{-3} = \frac{1}{2^3} = \frac{1}{8}$. El signo del exponente no cambia el signo del resultado.$exp$),
  ($id$expneg-f-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$easy$diff$, $prompt$Simplifica: $x^{-2}$$prompt$, $json$[{"latex":"\\frac{1}{x^2}","correct":true},{"latex":"-x^2","correct":false},{"latex":"x^2","correct":false},{"latex":"-\\frac{1}{x^2}","correct":false}]$json$::jsonb, $exp$$x^{-2} = \frac{1}{x^2}$. Un exponente negativo NO vuelve negativa a la base.$exp$),
  ($id$expneg-f-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$easy$diff$, $prompt$Simplifica: $5^{-1}$$prompt$, $json$[{"latex":"\\frac{1}{5}","correct":true},{"latex":"-5","correct":false},{"latex":"5","correct":false},{"latex":"0","correct":false}]$json$::jsonb, $exp$$5^{-1} = \frac{1}{5^1} = \frac{1}{5}$.$exp$),
  ($id$expneg-f-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$easy$diff$, $prompt$Simplifica: $a^{-1}$$prompt$, $json$[{"latex":"\\frac{1}{a}","correct":true},{"latex":"-a","correct":false},{"latex":"a","correct":false},{"latex":"-\\frac{1}{a}","correct":false}]$json$::jsonb, $exp$$a^{-1} = \frac{1}{a}$, que es el recíproco de $a$.$exp$),
  ($id$expneg-f-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$easy$diff$, $prompt$Simplifica: $10^{-2}$$prompt$, $json$[{"latex":"\\frac{1}{100}","correct":true},{"latex":"-100","correct":false},{"latex":"100","correct":false},{"latex":"-20","correct":false}]$json$::jsonb, $exp$$10^{-2} = \frac{1}{10^2} = \frac{1}{100}$.$exp$),
  ($id$expneg-m-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$medium$diff$, $prompt$Simplifica: $3x^{-2}$$prompt$, $json$[{"latex":"\\frac{3}{x^2}","correct":true},{"latex":"3x^2","correct":false},{"latex":"-3x^2","correct":false},{"latex":"\\frac{1}{3x^2}","correct":false}]$json$::jsonb, $exp$Solo la $x$ tiene exponente negativo: $3 \cdot x^{-2} = \frac{3}{x^2}$. El 3 queda arriba.$exp$),
  ($id$expneg-m-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$medium$diff$, $prompt$Simplifica: $(2x)^{-1}$$prompt$, $json$[{"latex":"\\frac{1}{2x}","correct":true},{"latex":"-2x","correct":false},{"latex":"\\frac{2}{x}","correct":false},{"latex":"2x","correct":false}]$json$::jsonb, $exp$El exponente aplica a toda la base: $(2x)^{-1} = \frac{1}{2x}$.$exp$),
  ($id$expneg-m-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$medium$diff$, $prompt$Simplifica: $(-2)^{-2}$$prompt$, $json$[{"latex":"\\frac{1}{4}","correct":true},{"latex":"-\\frac{1}{4}","correct":false},{"latex":"4","correct":false},{"latex":"-4","correct":false}]$json$::jsonb, $exp$$(-2)^{-2} = \frac{1}{(-2)^2} = \frac{1}{4}$. El exponente par elimina el signo.$exp$),
  ($id$expneg-m-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$medium$diff$, $prompt$Simplifica: $\frac{1}{x^{-2}}$$prompt$, $json$[{"latex":"x^2","correct":true},{"latex":"\\frac{1}{x^2}","correct":false},{"latex":"-x^2","correct":false},{"latex":"x^{-2}","correct":false}]$json$::jsonb, $exp$$\frac{1}{x^{-2}} = x^2$, porque un exponente negativo en el denominador sube al numerador.$exp$),
  ($id$expneg-m-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$medium$diff$, $prompt$Simplifica: $(3^{-1})^{-1}$$prompt$, $json$[{"latex":"3","correct":true},{"latex":"\\frac{1}{3}","correct":false},{"latex":"-3","correct":false},{"latex":"\\frac{1}{9}","correct":false}]$json$::jsonb, $exp$Se multiplican los exponentes: $(-1) \cdot (-1) = 1$, por lo que $3^1 = 3$.$exp$),
  ($id$expneg-h-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$hard$diff$, $prompt$Simplifica: $2^{-2} \cdot 2^3$$prompt$, $json$[{"latex":"2","correct":true},{"latex":"\\frac{1}{2}","correct":false},{"latex":"8","correct":false},{"latex":"\\frac{1}{8}","correct":false}]$json$::jsonb, $exp$Suma de exponentes: $-2 + 3 = 1$, por lo que $2^1 = 2$.$exp$),
  ($id$expneg-h-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$hard$diff$, $prompt$Simplifica: $\frac{x^2}{x^{-3}}$$prompt$, $json$[{"latex":"x^5","correct":true},{"latex":"x^{-1}","correct":false},{"latex":"x^{-5}","correct":false},{"latex":"x^6","correct":false}]$json$::jsonb, $exp$Resta de exponentes: $2 - (-3) = 2 + 3 = 5$, por lo que $x^5$.$exp$),
  ($id$expneg-h-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$hard$diff$, $prompt$Si $2^x = \frac{1}{8}$, ¿cuál es el valor de $x$?$prompt$, $json$[{"latex":"-3","correct":true},{"latex":"3","correct":false},{"latex":"-8","correct":false},{"latex":"\\frac{1}{3}","correct":false}]$json$::jsonb, $exp$$\frac{1}{8} = \frac{1}{2^3} = 2^{-3}$, por lo que $x = -3$.$exp$),
  ($id$expneg-h-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$hard$diff$, $prompt$Simplifica: $(2x^2)^{-2}$$prompt$, $json$[{"latex":"\\frac{1}{4x^4}","correct":true},{"latex":"\\frac{1}{2x^4}","correct":false},{"latex":"4x^4","correct":false},{"latex":"\\frac{4}{x^4}","correct":false}]$json$::jsonb, $exp$$(2x^2)^{-2} = \frac{1}{(2x^2)^2} = \frac{1}{4x^4}$.$exp$),
  ($id$expneg-h-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-negativo$law$, $diff$hard$diff$, $prompt$Simplifica: $\frac{3x^{-2}}{y^{-3}}$$prompt$, $json$[{"latex":"\\frac{3y^3}{x^2}","correct":true},{"latex":"\\frac{3x^2}{y^3}","correct":false},{"latex":"\\frac{3}{x^2 y^3}","correct":false},{"latex":"\\frac{x^2}{3y^3}","correct":false}]$json$::jsonb, $exp$Los exponentes negativos cambian de lugar: $\frac{3x^{-2}}{y^{-3}} = 3 \cdot \frac{y^3}{x^2} = \frac{3y^3}{x^2}$.$exp$),
  ($id$expfrac-f-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$easy$diff$, $prompt$Simplifica: $4^{1/2}$$prompt$, $json$[{"latex":"2","correct":true},{"latex":"4","correct":false},{"latex":"\\frac{1}{2}","correct":false},{"latex":"16","correct":false}]$json$::jsonb, $exp$$4^{1/2} = \sqrt{4} = 2$. El exponente $1/2$ es la raíz cuadrada.$exp$),
  ($id$expfrac-f-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$easy$diff$, $prompt$Simplifica: $x^{1/2}$$prompt$, $json$[{"latex":"\\sqrt{x}","correct":true},{"latex":"x","correct":false},{"latex":"x^2","correct":false},{"latex":"\\frac{1}{x}","correct":false}]$json$::jsonb, $exp$$x^{1/2} = \sqrt{x}$. El exponente fraccionario se convierte en radical.$exp$),
  ($id$expfrac-f-03$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$easy$diff$, $prompt$Simplifica: $9^{1/2}$$prompt$, $json$[{"latex":"3","correct":true},{"latex":"9","correct":false},{"latex":"\\frac{1}{3}","correct":false},{"latex":"81","correct":false}]$json$::jsonb, $exp$$9^{1/2} = \sqrt{9} = 3$.$exp$),
  ($id$expfrac-f-04$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$easy$diff$, $prompt$Simplifica: $8^{1/3}$$prompt$, $json$[{"latex":"2","correct":true},{"latex":"4","correct":false},{"latex":"8","correct":false},{"latex":"\\frac{1}{2}","correct":false}]$json$::jsonb, $exp$$8^{1/3} = \sqrt[3]{8} = 2$, porque $2^3 = 8$.$exp$),
  ($id$expfrac-f-05$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$easy$diff$, $prompt$Simplifica: $16^{1/2}$$prompt$, $json$[{"latex":"4","correct":true},{"latex":"16","correct":false},{"latex":"8","correct":false},{"latex":"\\frac{1}{4}","correct":false}]$json$::jsonb, $exp$$16^{1/2} = \sqrt{16} = 4$.$exp$),
  ($id$expfrac-m-01$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$medium$diff$, $prompt$Simplifica: $8^{2/3}$$prompt$, $json$[{"latex":"4","correct":true},{"latex":"2","correct":false},{"latex":"16","correct":false},{"latex":"64","correct":false}]$json$::jsonb, $exp$$8^{2/3} = (\sqrt[3]{8})^2 = 2^2 = 4$. Primero la raíz, luego la potencia.$exp$),
  ($id$expfrac-m-02$id$, $sec$algebra$sec$, $sub$exponentes$sub$, $law$exponente-fraccionario$law$, $diff$medium$diff$, $prompt$Simplifica: $27^{1/3}$$prompt$, $json$[{"latex":"3","correct":true},{"latex":"9","correct":false},{"latex":"27","correct":false},{"latex":"\\frac{1}{3}","correct":false}]$json$::jsonb, $exp$$27^{1/3} = \sqrt[3]{27} = 3$, porque $3^3 = 27$.$exp$)
