  ($id$logprod-m-01$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$medium$diff$, $prompt$Combina: $\log 3 + \log 4$$prompt$, $json$[{"latex":"\\log 12","correct":true},{"latex":"\\log 7","correct":false},{"latex":"\\log 34","correct":false},{"latex":"\\log(3/4)","correct":false}]$json$::jsonb, $exp$$\log 3 + \log 4 = \log(3 \cdot 4) = \log 12$.$exp$),
  ($id$logprod-m-02$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$medium$diff$, $prompt$Expande: $\log_5(125 \cdot 5)$$prompt$, $json$[{"latex":"\\log_5 125 + \\log_5 5","correct":true},{"latex":"\\log_5 125 \\cdot \\log_5 5","correct":false},{"latex":"\\log_5 130","correct":false},{"latex":"\\log_5 125 - \\log_5 5","correct":false}]$json$::jsonb, $exp$$\log_5(125 \cdot 5) = \log_5 125 + \log_5 5$.$exp$),
  ($id$logprod-m-03$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$medium$diff$, $prompt$Simplifica: $\log_2(xy) - \log_2 y$$prompt$, $json$[{"latex":"\\log_2 x","correct":true},{"latex":"\\log_2(xy)","correct":false},{"latex":"\\log_2(xy^2)","correct":false},{"latex":"\\log_2(x + y)","correct":false}]$json$::jsonb, $exp$$\log_2(xy) - \log_2 y = \log_2\left(\frac{xy}{y}\right) = \log_2 x$.$exp$),
