  ($id$logprod-m-05$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$medium$diff$, $prompt$Combina: $\log a + \log b + \log c$$prompt$, $json$[{"latex":"\\log(abc)","correct":true},{"latex":"\\log(a + b + c)","correct":false},{"latex":"3 \\log a","correct":false},{"latex":"\\log(a/bc)","correct":false}]$json$::jsonb, $exp$$\log a + \log b + \log c = \log(abc)$.$exp$),
  ($id$logprod-h-01$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$hard$diff$, $prompt$Si $\log 2 = 0.301$, ¿cuánto vale $\log 20$?$prompt$, $json$[{"latex":"1.301","correct":true},{"latex":"0.602","correct":false},{"latex":"2.301","correct":false},{"latex":"3.01","correct":false}]$json$::jsonb, $exp$$\log 20 = \log(2 \cdot 10) = \log 2 + \log 10 = 0.301 + 1 = 1.301$.$exp$),
  ($id$logprod-h-02$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$hard$diff$, $prompt$Si $\log 2 = a$ y $\log 3 = b$, ¿cuánto vale $\log 6$?$prompt$, $json$[{"latex":"a + b","correct":true},{"latex":"a \\cdot b","correct":false},{"latex":"a - b","correct":false},{"latex":"2a + 3b","correct":false}]$json$::jsonb, $exp$$\log 6 = \log(2 \cdot 3) = \log 2 + \log 3 = a + b$.$exp$),
  ($id$logprod-h-03$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$hard$diff$, $prompt$Simplifica: $\log_2(x^2 y) - \log_2 x$$prompt$, $json$[{"latex":"\\log_2(xy)","correct":true},{"latex":"\\log_2(x^2 y)","correct":false},{"latex":"\\log_2 x","correct":false},{"latex":"\\log_2(x^2 y^2)","correct":false}]$json$::jsonb, $exp$$\log_2(x^2 y) - \log_2 x = \log_2\left(\frac{x^2 y}{x}\right) = \log_2(xy)$.$exp$),
  ($id$logprod-h-04$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$hard$diff$, $prompt$Si $\log x = 2$ y $\log y = 3$, ¿cuánto vale $\log(xy)$?$prompt$, $json$[{"latex":"5","correct":true},{"latex":"6","correct":false},{"latex":"1","correct":false},{"latex":"9","correct":false}]$json$::jsonb, $exp$$\log(xy) = \log x + \log y = 2 + 3 = 5$.$exp$),
  ($id$logprod-h-05$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-producto$law$, $diff$hard$diff$, $prompt$Combina: $\log_7 3 + \log_7 \frac{1}{3}$$prompt$, $json$[{"latex":"0","correct":true},{"latex":"1","correct":false},{"latex":"\\log_7 9","correct":false},{"latex":"-1","correct":false}]$json$::jsonb, $exp$$\log_7 3 + \log_7 \frac{1}{3} = \log_7\left(3 \cdot \frac{1}{3}\right) = \log_7 1 = 0$.$exp$),
  ($id$logcoc-f-01$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$easy$diff$, $prompt$¿A qué es igual $\log_a(x/y)$?$prompt$, $json$[{"latex":"\\log_a x - \\log_a y","correct":true},{"latex":"\\log_a x + \\log_a y","correct":false},{"latex":"\\log_a x \\cdot \\log_a y","correct":false},{"latex":"\\frac{\\log_a x}{\\log_a y}","correct":false}]$json$::jsonb, $exp$$\log_a(x/y) = \log_a x - \log_a y$. El logaritmo de un cociente es la resta de logaritmos.$exp$),
  ($id$logcoc-f-02$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$easy$diff$, $prompt$Expande: $\log_{10}(8/2)$$prompt$, $json$[{"latex":"\\log_{10} 8 - \\log_{10} 2","correct":true},{"latex":"\\log_{10} 8 + \\log_{10} 2","correct":false},{"latex":"\\frac{\\log_{10} 8}{\\log_{10} 2}","correct":false},{"latex":"\\log_{10} 6","correct":false}]$json$::jsonb, $exp$$\log_{10}(8/2) = \log_{10} 8 - \log_{10} 2$.$exp$),
  ($id$logcoc-f-03$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$easy$diff$, $prompt$Combina: $\log_2 x - \log_2 y$$prompt$, $json$[{"latex":"\\log_2(x/y)","correct":true},{"latex":"\\log_2(xy)","correct":false},{"latex":"\\log_2(x - y)","correct":false},{"latex":"\\frac{\\log_2 x}{\\log_2 y}","correct":false}]$json$::jsonb, $exp$La resta de logaritmos de la misma base es el logaritmo del cociente: $\log_2(x/y)$.$exp$),
  ($id$logcoc-f-04$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$easy$diff$, $prompt$¿Cuánto vale $\log_{10} 100 - \log_{10} 10$?$prompt$, $json$[{"latex":"1","correct":true},{"latex":"10","correct":false},{"latex":"\\log_{10} 90","correct":false},{"latex":"90","correct":false}]$json$::jsonb, $exp$$\log_{10} 100 - \log_{10} 10 = \log_{10}(100/10) = \log_{10} 10 = 1$.$exp$),
  ($id$logcoc-f-05$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$easy$diff$, $prompt$Expande: $\log_5(x/25)$$prompt$, $json$[{"latex":"\\log_5 x - \\log_5 25","correct":true},{"latex":"\\log_5 x + \\log_5 25","correct":false},{"latex":"\\frac{\\log_5 x}{\\log_5 25}","correct":false},{"latex":"\\log_5(x - 25)","correct":false}]$json$::jsonb, $exp$$\log_5(x/25) = \log_5 x - \log_5 25$.$exp$),
  ($id$logcoc-m-01$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$medium$diff$, $prompt$Combina: $\log 20 - \log 4$$prompt$, $json$[{"latex":"\\log 5","correct":true},{"latex":"\\log 16","correct":false},{"latex":"\\log 80","correct":false},{"latex":"\\log 24","correct":false}]$json$::jsonb, $exp$$\log 20 - \log 4 = \log(20/4) = \log 5$.$exp$),
  ($id$logcoc-m-02$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$medium$diff$, $prompt$Expande: $\log_3(27/9)$$prompt$, $json$[{"latex":"\\log_3 27 - \\log_3 9","correct":true},{"latex":"\\log_3 27 + \\log_3 9","correct":false},{"latex":"\\frac{\\log_3 27}{\\log_3 9}","correct":false},{"latex":"\\log_3 18","correct":false}]$json$::jsonb, $exp$$\log_3(27/9) = \log_3 27 - \log_3 9$.$exp$),
  ($id$logcoc-m-03$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$medium$diff$, $prompt$Simplifica: $\log(x^2) - \log x$$prompt$, $json$[{"latex":"\\log x","correct":true},{"latex":"\\log(x^2)","correct":false},{"latex":"\\log(x^3)","correct":false},{"latex":"\\log(2x)","correct":false}]$json$::jsonb, $exp$$\log(x^2) - \log x = \log(x^2/x) = \log x$.$exp$),
  ($id$logcoc-m-04$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$medium$diff$, $prompt$¿Cuánto vale $\log_6 12 - \log_6 2$?$prompt$, $json$[{"latex":"1","correct":true},{"latex":"6","correct":false},{"latex":"\\log_6 10","correct":false},{"latex":"10","correct":false}]$json$::jsonb, $exp$$\log_6 12 - \log_6 2 = \log_6(12/2) = \log_6 6 = 1$.$exp$),
  ($id$logcoc-m-05$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$medium$diff$, $prompt$Combina: $\log a - \log b - \log c$$prompt$, $json$[{"latex":"\\log\\left(\\frac{a}{bc}\\right)","correct":true},{"latex":"\\log(a - b - c)","correct":false},{"latex":"\\log\\left(\\frac{a}{b + c}\\right)","correct":false},{"latex":"\\log(abc)","correct":false}]$json$::jsonb, $exp$$\log a - \log b - \log c = \log\left(\frac{a}{bc}\right)$.$exp$),
  ($id$logcoc-h-01$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$hard$diff$, $prompt$Si $\log 2 = 0.301$, ¿cuánto vale $\log 5$?$prompt$, $json$[{"latex":"0.699","correct":true},{"latex":"0.301","correct":false},{"latex":"0.5","correct":false},{"latex":"1.301","correct":false}]$json$::jsonb, $exp$$\log 5 = \log(10/2) = \log 10 - \log 2 = 1 - 0.301 = 0.699$.$exp$),
  ($id$logcoc-h-02$id$, $sec$algebra$sec$, $sub$logaritmos$sub$, $law$log-cociente$law$, $diff$hard$diff$, $prompt$Si $\log x = 4$ y $\log y = 1$, ¿cuánto vale $\log(x/y)$?$prompt$, $json$[{"latex":"3","correct":true},{"latex":"5","correct":false},{"latex":"4","correct":false},{"latex":"0.25","correct":false}]$json$::jsonb, $exp$$\log(x/y) = \log x - \log y = 4 - 1 = 3$.$exp$)
