  ($id$tricp-m-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$medium$diff$, $prompt$Factoriza: $9x^2 - 6x + 1$$prompt$, $json$[{"latex":"(3x - 1)^2","correct":true},{"latex":"(3x + 1)^2","correct":false},{"latex":"(3x - 1)(3x + 1)","correct":false},{"latex":"(9x - 1)^2","correct":false}]$json$::jsonb, $exp$$9x^2 - 6x + 1 = (3x-1)^2$ porque $(3x)^2 = 9x^2$ y $2(3x)(1) = 6x$.$exp$),
  ($id$tricp-m-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$medium$diff$, $prompt$Factoriza: $x^2 + 2xy + y^2$$prompt$, $json$[{"latex":"(x + y)^2","correct":true},{"latex":"(x - y)^2","correct":false},{"latex":"(x + y)(x - y)","correct":false},{"latex":"x^2 + y^2","correct":false}]$json$::jsonb, $exp$$x^2 + 2xy + y^2 = (x+y)^2$.$exp$),
  ($id$tricp-m-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$medium$diff$, $prompt$¿Cuál de los siguientes es un trinomio cuadrado perfecto?$prompt$, $json$[{"latex":"x^2 + 8x + 16","correct":true},{"latex":"x^2 + 8x + 8","correct":false},{"latex":"x^2 + 16x + 8","correct":false},{"latex":"x^2 + 4x + 16","correct":false}]$json$::jsonb, $exp$$x^2 + 8x + 16 = (x+4)^2$ porque $2 \cdot 4 = 8$ y $4^2 = 16$. Los demás no cumplen que el término constante sea el cuadrado de la mitad del coeficiente.$exp$),
  ($id$tricp-m-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$medium$diff$, $prompt$Factoriza: $25x^2 - 20x + 4$$prompt$, $json$[{"latex":"(5x - 2)^2","correct":true},{"latex":"(5x + 2)^2","correct":false},{"latex":"(5x - 2)(5x + 2)","correct":false},{"latex":"(5x - 4)^2","correct":false}]$json$::jsonb, $exp$$25x^2 - 20x + 4 = (5x-2)^2$ porque $(5x)^2 = 25x^2$ y $2^2 = 4$.$exp$),
  ($id$tricp-h-01$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$hard$diff$, $prompt$¿Qué valor de $c$ hace que $x^2 + 10x + c$ sea un cuadrado perfecto?$prompt$, $json$[{"latex":"25","correct":true},{"latex":"10","correct":false},{"latex":"5","correct":false},{"latex":"100","correct":false}]$json$::jsonb, $exp$Para ser cuadrado perfecto, $c$ debe ser $(\frac{10}{2})^2 = 5^2 = 25$.$exp$),
  ($id$tricp-h-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$hard$diff$, $prompt$Factoriza: $x^4 + 2x^2 + 1$$prompt$, $json$[{"latex":"(x^2 + 1)^2","correct":true},{"latex":"(x^2 + 1)(x^2 - 1)","correct":false},{"latex":"(x + 1)^4","correct":false},{"latex":"x^4 + 1","correct":false}]$json$::jsonb, $exp$$x^4 + 2x^2 + 1 = (x^2+1)^2$, tratando a $x^2$ como la variable.$exp$),
  ($id$tricp-h-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$hard$diff$, $prompt$Factoriza: $4a^2 + 12ab + 9b^2$$prompt$, $json$[{"latex":"(2a + 3b)^2","correct":true},{"latex":"(2a + 3b)(2a - 3b)","correct":false},{"latex":"(2a + 9b)^2","correct":false},{"latex":"(4a + 9b)^2","correct":false}]$json$::jsonb, $exp$$4a^2 + 12ab + 9b^2 = (2a+3b)^2$ porque $(2a)^2 = 4a^2$ y $(3b)^2 = 9b^2$.$exp$),
  ($id$tricp-h-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$hard$diff$, $prompt$¿Para qué valor de $n$ es $x^2 + nx + 49$ un cuadrado perfecto?$prompt$, $json$[{"latex":"14","correct":true},{"latex":"7","correct":false},{"latex":"49","correct":false},{"latex":"98","correct":false}]$json$::jsonb, $exp$Como $49 = 7^2$, se necesita $n = 2 \cdot 7 = 14$ para que sea $(x+7)^2$.$exp$),
  ($id$tricp-h-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$hard$diff$, $prompt$Factoriza: $9x^2 - 12xy + 4y^2$$prompt$, $json$[{"latex":"(3x - 2y)^2","correct":true},{"latex":"(3x + 2y)^2","correct":false},{"latex":"(3x - 2y)(3x + 2y)","correct":false},{"latex":"(9x - 4y)^2","correct":false}]$json$::jsonb, $exp$$9x^2 - 12xy + 4y^2 = (3x-2y)^2$ porque $(3x)^2 = 9x^2$ y $(2y)^2 = 4y^2$.$exp$),
  ($id$compop-f-01$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$easy$diff$, $prompt$¿Cuánto vale $i^2$?$prompt$, $json$[{"latex":"-1","correct":true},{"latex":"1","correct":false},{"latex":"i","correct":false},{"latex":"-i","correct":false}]$json$::jsonb, $exp$Por definición, $i^2 = -1$. Es la base de los números complejos.$exp$),
  ($id$compop-f-02$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$easy$diff$, $prompt$Suma: $(2 + 3i) + (1 + 4i)$$prompt$, $json$[{"latex":"3 + 7i","correct":true},{"latex":"7 + 3i","correct":false},{"latex":"2 + 7i","correct":false},{"latex":"3 - 7i","correct":false}]$json$::jsonb, $exp$Suma partes reales e imaginarias por separado: $(2+1) + (3+4)i = 3 + 7i$.$exp$)
INSERT INTO public.questions (id, section_id, subtema_id, law_id, difficulty, prompt, options, explanation)
VALUES
  ($id$compop-f-03$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$easy$diff$, $prompt$Resta: $(5 + 2i) - (3 + i)$$prompt$, $json$[{"latex":"2 + i","correct":true},{"latex":"2 - i","correct":false},{"latex":"8 + 3i","correct":false},{"latex":"2 + 3i","correct":false}]$json$::jsonb, $exp$$(5-3) + (2-1)i = 2 + i$.$exp$),
  ($id$compop-f-04$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$easy$diff$, $prompt$¿Cuál es el conjugado de $3 + 4i$?$prompt$, $json$[{"latex":"3 - 4i","correct":true},{"latex":"-3 + 4i","correct":false},{"latex":"-3 - 4i","correct":false},{"latex":"4 + 3i","correct":false}]$json$::jsonb, $exp$El conjugado cambia el signo de la parte imaginaria: $3 - 4i$.$exp$),
  ($id$compop-f-05$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$easy$diff$, $prompt$Suma: $(1 + i) + (1 - i)$$prompt$, $json$[{"latex":"2","correct":true},{"latex":"2i","correct":false},{"latex":"0","correct":false},{"latex":"1 + i","correct":false}]$json$::jsonb, $exp$Las partes imaginarias se cancelan: $(1+1) + (i - i) = 2$.$exp$),
  ($id$compop-m-01$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$medium$diff$, $prompt$Multiplica: $(2i)(3i)$$prompt$, $json$[{"latex":"-6","correct":true},{"latex":"6","correct":false},{"latex":"6i","correct":false},{"latex":"-6i","correct":false}]$json$::jsonb, $exp$$(2i)(3i) = 6i^2 = 6(-1) = -6$.$exp$),
  ($id$compop-m-02$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$medium$diff$, $prompt$Multiplica: $(1 + i)(1 - i)$$prompt$, $json$[{"latex":"2","correct":true},{"latex":"0","correct":false},{"latex":"1","correct":false},{"latex":"2i","correct":false}]$json$::jsonb, $exp$$(1+i)(1-i) = 1 - i^2 = 1 - (-1) = 2$. Un complejo por su conjugado da un real.$exp$),
  ($id$compop-m-03$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$medium$diff$, $prompt$Multiplica: $(2 + i)(1 + i)$$prompt$, $json$[{"latex":"1 + 3i","correct":true},{"latex":"3 + 3i","correct":false},{"latex":"1 + i","correct":false},{"latex":"2 + 3i","correct":false}]$json$::jsonb, $exp$$2 + 2i + i + i^2 = 2 + 3i - 1 = 1 + 3i$.$exp$),
  ($id$compop-m-04$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$medium$diff$, $prompt$¿Cuánto vale $i^3$?$prompt$, $json$[{"latex":"-i","correct":true},{"latex":"i","correct":false},{"latex":"-1","correct":false},{"latex":"1","correct":false}]$json$::jsonb, $exp$$i^3 = i^2 \cdot i = (-1) \cdot i = -i$.$exp$),
  ($id$compop-m-05$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$medium$diff$, $prompt$Multiplica: $(3 + 2i)(3 - 2i)$$prompt$, $json$[{"latex":"13","correct":true},{"latex":"5","correct":false},{"latex":"9","correct":false},{"latex":"13i","correct":false}]$json$::jsonb, $exp$$(3+2i)(3-2i) = 9 - 4i^2 = 9 + 4 = 13$.$exp$),
  ($id$compop-h-01$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$hard$diff$, $prompt$Divide: $\frac{1 + i}{1 - i}$$prompt$, $json$[{"latex":"i","correct":true},{"latex":"-i","correct":false},{"latex":"1","correct":false},{"latex":"2i","correct":false}]$json$::jsonb, $exp$Multiplica por el conjugado: $\frac{(1+i)(1+i)}{(1-i)(1+i)} = \frac{2i}{2} = i$.$exp$),
  ($id$compop-h-02$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$hard$diff$, $prompt$Divide: $\frac{2 + 3i}{1 + i}$$prompt$, $json$[{"latex":"\\frac{5}{2} + \\frac{1}{2}i","correct":true},{"latex":"\\frac{5}{2} - \\frac{1}{2}i","correct":false},{"latex":"1 + i","correct":false},{"latex":"2 + i","correct":false}]$json$::jsonb, $exp$$\frac{(2+3i)(1-i)}{(1+i)(1-i)} = \frac{5 + i}{2} = \frac{5}{2} + \frac{1}{2}i$.$exp$),
  ($id$compop-h-03$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$hard$diff$, $prompt$¿Cuánto vale $i^4$?$prompt$, $json$[{"latex":"1","correct":true},{"latex":"-1","correct":false},{"latex":"i","correct":false},{"latex":"-i","correct":false}]$json$::jsonb, $exp$$i^4 = (i^2)^2 = (-1)^2 = 1$.$exp$),
  ($id$compop-h-04$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$hard$diff$, $prompt$Simplifica: $(1 + i)^2$$prompt$, $json$[{"latex":"2i","correct":true},{"latex":"2","correct":false},{"latex":"1 + 2i","correct":false},{"latex":"-2i","correct":false}]$json$::jsonb, $exp$$(1+i)^2 = 1 + 2i + i^2 = 1 + 2i - 1 = 2i$.$exp$),
  ($id$compop-h-05$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-operaciones$law$, $diff$hard$diff$, $prompt$Divide: $\frac{4 + 2i}{2}$$prompt$, $json$[{"latex":"2 + i","correct":true},{"latex":"2 - i","correct":false},{"latex":"4 + i","correct":false},{"latex":"2 + 2i","correct":false}]$json$::jsonb, $exp$$\frac{4}{2} + \frac{2i}{2} = 2 + i$.$exp$),
  ($id$comppol-f-01$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$easy$diff$, $prompt$¿Cuál es el módulo de $3 + 4i$?$prompt$, $json$[{"latex":"5","correct":true},{"latex":"7","correct":false},{"latex":"25","correct":false},{"latex":"\\sqrt{7}","correct":false}]$json$::jsonb, $exp$$|3+4i| = \sqrt{3^2 + 4^2} = \sqrt{9+16} = \sqrt{25} = 5$.$exp$),
  ($id$comppol-f-02$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$easy$diff$, $prompt$¿Cuál es el módulo de $1 + i$?$prompt$, $json$[{"latex":"\\sqrt{2}","correct":true},{"latex":"2","correct":false},{"latex":"1","correct":false},{"latex":"\\sqrt{3}","correct":false}]$json$::jsonb, $exp$$|1+i| = \sqrt{1^2 + 1^2} = \sqrt{2}$.$exp$),
  ($id$comppol-f-03$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$easy$diff$, $prompt$¿Cuál es el módulo de $5i$?$prompt$, $json$[{"latex":"5","correct":true},{"latex":"0","correct":false},{"latex":"25","correct":false},{"latex":"i","correct":false}]$json$::jsonb, $exp$$|5i| = \sqrt{0^2 + 5^2} = 5$.$exp$),
  ($id$comppol-f-04$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$easy$diff$, $prompt$El módulo de $z = a + bi$ es...$prompt$, $json$[{"latex":"\\sqrt{a^2 + b^2}","correct":true},{"latex":"a + b","correct":false},{"latex":"a^2 + b^2","correct":false},{"latex":"\\sqrt{a - b}","correct":false}]$json$::jsonb, $exp$$|z| = \sqrt{a^2 + b^2}$, la distancia al origen en el plano complejo.$exp$),
  ($id$comppol-f-05$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$easy$diff$, $prompt$¿Cuál es el módulo de $6 + 8i$?$prompt$, $json$[{"latex":"10","correct":true},{"latex":"14","correct":false},{"latex":"100","correct":false},{"latex":"\\sqrt{14}","correct":false}]$json$::jsonb, $exp$$|6+8i| = \sqrt{36 + 64} = \sqrt{100} = 10$.$exp$),
  ($id$comppol-m-01$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$medium$diff$, $prompt$¿Cuál es el módulo de $1 + \sqrt{3}\,i$?$prompt$, $json$[{"latex":"2","correct":true},{"latex":"4","correct":false},{"latex":"\\sqrt{3}","correct":false},{"latex":"1 + \\sqrt{3}","correct":false}]$json$::jsonb, $exp$$|1+\sqrt{3}i| = \sqrt{1 + 3} = \sqrt{4} = 2$.$exp$),
  ($id$comppol-m-02$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$medium$diff$, $prompt$¿Cuál es el argumento de $1 + i$?$prompt$, $json$[{"latex":"45^\\circ","correct":true},{"latex":"90^\\circ","correct":false},{"latex":"30^\\circ","correct":false},{"latex":"60^\\circ","correct":false}]$json$::jsonb, $exp$$1 + i$ está en el primer cuadrante con partes iguales, así que su ángulo es $45^\circ$.$exp$),
  ($id$comppol-m-03$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$medium$diff$, $prompt$¿Cuál es el módulo de $-3 + 4i$?$prompt$, $json$[{"latex":"5","correct":true},{"latex":"1","correct":false},{"latex":"7","correct":false},{"latex":"-5","correct":false}]$json$::jsonb, $exp$$|-3+4i| = \sqrt{(-3)^2 + 4^2} = \sqrt{9+16} = 5$. El módulo siempre es positivo.$exp$),
  ($id$comppol-m-04$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$medium$diff$, $prompt$Escribe $2(\cos 60^\circ + i \sin 60^\circ)$ en forma rectangular$prompt$, $json$[{"latex":"1 + \\sqrt{3}\\,i","correct":true},{"latex":"\\sqrt{3} + i","correct":false},{"latex":"2 + \\sqrt{3}\\,i","correct":false},{"latex":"1 + i","correct":false}]$json$::jsonb, $exp$$2\cos 60^\circ = 2 \cdot \frac12 = 1$ y $2\sin 60^\circ = 2 \cdot \frac{\sqrt3}{2} = \sqrt3$. Resultado: $1 + \sqrt{3}i$.$exp$),
  ($id$comppol-m-05$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$medium$diff$, $prompt$¿Cuál es el módulo de $2 - 2i$?$prompt$, $json$[{"latex":"2\\sqrt{2}","correct":true},{"latex":"4","correct":false},{"latex":"2","correct":false},{"latex":"8","correct":false}]$json$::jsonb, $exp$$|2-2i| = \sqrt{4 + 4} = \sqrt{8} = 2\sqrt{2}$.$exp$),
  ($id$comppol-h-01$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$hard$diff$, $prompt$Si $z = 3 + 4i$ y $w = 1 + 2i$, ¿cuánto vale $|z \cdot w|$?$prompt$, $json$[{"latex":"5\\sqrt{5}","correct":true},{"latex":"5 + \\sqrt{5}","correct":false},{"latex":"\\sqrt{5}","correct":false},{"latex":"25","correct":false}]$json$::jsonb, $exp$$|z \cdot w| = |z| \cdot |w| = 5 \cdot \sqrt{5} = 5\sqrt{5}$.$exp$),
  ($id$comppol-h-02$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$hard$diff$, $prompt$¿Cuál es el argumento de $-1 + i$?$prompt$, $json$[{"latex":"135^\\circ","correct":true},{"latex":"45^\\circ","correct":false},{"latex":"225^\\circ","correct":false},{"latex":"315^\\circ","correct":false}]$json$::jsonb, $exp$$-1 + i$ está en el segundo cuadrante, así que su argumento es $180^\circ - 45^\circ = 135^\circ$.$exp$),
  ($id$comppol-h-03$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$hard$diff$, $prompt$Usa De Moivre: $(\cos 30^\circ + i \sin 30^\circ)^3 = ?$$prompt$, $json$[{"latex":"i","correct":true},{"latex":"1","correct":false},{"latex":"-i","correct":false},{"latex":"-1","correct":false}]$json$::jsonb, $exp$De Moivre multiplica el ángulo: $3 \cdot 30^\circ = 90^\circ$. $\cos 90^\circ + i\sin 90^\circ = i$.$exp$),
  ($id$comppol-h-04$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$hard$diff$, $prompt$¿Cuál es el módulo de $\frac{3 + 4i}{1 + 2i}$?$prompt$, $json$[{"latex":"\\sqrt{5}","correct":true},{"latex":"5\\sqrt{5}","correct":false},{"latex":"5","correct":false},{"latex":"\\frac{1}{\\sqrt{5}}","correct":false}]$json$::jsonb, $exp$$\left|\frac{z}{w}\right| = \frac{|z|}{|w|} = \frac{5}{\sqrt{5}} = \sqrt{5}$.$exp$),
  ($id$comppol-h-05$id$, $sec$algebra$sec$, $sub$complejos$sub$, $law$complejos-forma-polar$law$, $diff$hard$diff$, $prompt$Escribe $4(\cos 90^\circ + i \sin 90^\circ)$ en forma rectangular$prompt$, $json$[{"latex":"4i","correct":true},{"latex":"4","correct":false},{"latex":"-4i","correct":false},{"latex":"4 + 4i","correct":false}]$json$::jsonb, $exp$$4\cos 90^\circ = 0$ y $4\sin 90^\circ = 4$. Resultado: $4i$.$exp$),
  ($id$cuad-f-01$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$easy$diff$, $prompt$En $ax^2 + bx + c = 0$, ¿cuál es la fórmula general?$prompt$, $json$[{"latex":"x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}","correct":true},{"latex":"x = \\frac{-b \\pm \\sqrt{b^2 + 4ac}}{2a}","correct":false},{"latex":"x = \\frac{b \\pm \\sqrt{b^2 - 4ac}}{2a}","correct":false},{"latex":"x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{a}","correct":false}]$json$::jsonb, $exp$La fórmula general es $x = \frac{-b \pm \sqrt{b^2 - 4ac}}{2a}$. El discriminante es $b^2 - 4ac$.$exp$),
  ($id$cuad-f-02$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$easy$diff$, $prompt$Resuelve: $x^2 - 4 = 0$$prompt$, $json$[{"latex":"x = \\pm 2","correct":true},{"latex":"x = 2","correct":false},{"latex":"x = 4","correct":false},{"latex":"x = \\pm 4","correct":false}]$json$::jsonb, $exp$$x^2 = 4$, por lo que $x = \pm 2$.$exp$),
  ($id$cuad-f-03$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$easy$diff$, $prompt$Resuelve: $x^2 - 9 = 0$$prompt$, $json$[{"latex":"x = \\pm 3","correct":true},{"latex":"x = 3","correct":false},{"latex":"x = 9","correct":false},{"latex":"x = \\pm 9","correct":false}]$json$::jsonb, $exp$$x^2 = 9$, por lo que $x = \pm 3$.$exp$),
  ($id$cuad-f-04$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$easy$diff$, $prompt$¿Cuál es el discriminante de $x^2 + 2x + 1 = 0$?$prompt$, $json$[{"latex":"0","correct":true},{"latex":"4","correct":false},{"latex":"1","correct":false},{"latex":"-4","correct":false}]$json$::jsonb, $exp$$b^2 - 4ac = 2^2 - 4(1)(1) = 4 - 4 = 0$.$exp$),
  ($id$cuad-f-05$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$easy$diff$, $prompt$Resuelve: $x^2 - x = 0$$prompt$, $json$[{"latex":"x = 0 \\text{ o } x = 1","correct":true},{"latex":"x = 1 \\text{ o } x = -1","correct":false},{"latex":"x = 0 \\text{ o } x = -1","correct":false},{"latex":"x = 0","correct":false}]$json$::jsonb, $exp$Factoriza: $x(x - 1) = 0$, por lo que $x = 0$ o $x = 1$.$exp$),
  ($id$cuad-m-01$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$medium$diff$, $prompt$Resuelve: $x^2 - 5x + 6 = 0$$prompt$, $json$[{"latex":"x = 2 \\text{ y } x = 3","correct":true},{"latex":"x = -2 \\text{ y } x = -3","correct":false},{"latex":"x = 1 \\text{ y } x = 6","correct":false},{"latex":"x = -1 \\text{ y } x = -6","correct":false}]$json$::jsonb, $exp$Factoriza: $(x-2)(x-3) = 0$, por lo que $x = 2$ o $x = 3$.$exp$),
  ($id$cuad-m-02$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$medium$diff$, $prompt$Resuelve: $x^2 + 4x + 4 = 0$$prompt$, $json$[{"latex":"x = -2","correct":true},{"latex":"x = 2","correct":false},{"latex":"x = \\pm 2","correct":false},{"latex":"x = 4","correct":false}]$json$::jsonb, $exp$$x^2 + 4x + 4 = (x+2)^2 = 0$, por lo que $x = -2$ (raíz doble).$exp$),
  ($id$cuad-m-03$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$medium$diff$, $prompt$¿Cuántas soluciones reales tiene $x^2 + 1 = 0$?$prompt$, $json$[{"latex":"0","correct":true},{"latex":"1","correct":false},{"latex":"2","correct":false},{"latex":"\\text{infinitas}","correct":false}]$json$::jsonb, $exp$El discriminante es $0^2 - 4(1)(1) = -4 < 0$, así que no hay soluciones reales.$exp$),
  ($id$cuad-m-04$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$medium$diff$, $prompt$Resuelve: $2x^2 - 8 = 0$$prompt$, $json$[{"latex":"x = \\pm 2","correct":true},{"latex":"x = \\pm 4","correct":false},{"latex":"x = 2","correct":false},{"latex":"x = 4","correct":false}]$json$::jsonb, $exp$$2x^2 = 8 \Rightarrow x^2 = 4 \Rightarrow x = \pm 2$.$exp$),
  ($id$cuad-m-05$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$medium$diff$, $prompt$Si el discriminante $b^2 - 4ac = 0$, la ecuación tiene...$prompt$, $json$[{"latex":"\\text{una solución real (doble)}","correct":true},{"latex":"\\text{dos soluciones reales distintas}","correct":false},{"latex":"\\text{ninguna solución real}","correct":false},{"latex":"\\text{infinitas soluciones}","correct":false}]$json$::jsonb, $exp$Cuando el discriminante es 0, las dos raíces coinciden: hay una solución real doble.$exp$),
  ($id$cuad-h-01$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$hard$diff$, $prompt$Resuelve: $x^2 - 2x - 8 = 0$$prompt$, $json$[{"latex":"x = 4 \\text{ y } x = -2","correct":true},{"latex":"x = -4 \\text{ y } x = 2","correct":false},{"latex":"x = 2 \\text{ y } x = 4","correct":false},{"latex":"x = -2 \\text{ y } x = 8","correct":false}]$json$::jsonb, $exp$Factoriza: $(x-4)(x+2) = 0$, por lo que $x = 4$ o $x = -2$.$exp$),
  ($id$cuad-h-02$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$hard$diff$, $prompt$Resuelve: $2x^2 + 3x - 2 = 0$$prompt$, $json$[{"latex":"x = \\frac{1}{2} \\text{ y } x = -2","correct":true},{"latex":"x = -\\frac{1}{2} \\text{ y } x = 2","correct":false},{"latex":"x = 2 \\text{ y } x = -\\frac{1}{2}","correct":false},{"latex":"x = 1 \\text{ y } x = -2","correct":false}]$json$::jsonb, $exp$$x = \frac{-3 \pm \sqrt{9 + 16}}{4} = \frac{-3 \pm 5}{4}$, que da $\frac{1}{2}$ y $-2$.$exp$),
  ($id$cuad-h-03$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$hard$diff$, $prompt$Resuelve: $x^2 + 2x + 5 = 0$$prompt$, $json$[{"latex":"x = -1 \\pm 2i","correct":true},{"latex":"x = -1 \\pm 2","correct":false},{"latex":"x = 1 \\pm 2i","correct":false},{"latex":"x = -2 \\pm i","correct":false}]$json$::jsonb, $exp$$x = \frac{-2 \pm \sqrt{4 - 20}}{2} = \frac{-2 \pm 4i}{2} = -1 \pm 2i$. Raíces complejas.$exp$),
  ($id$cuad-h-04$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$hard$diff$, $prompt$Si una raíz de $x^2 - 7x + k = 0$ es $2$, ¿cuánto vale $k$?$prompt$, $json$[{"latex":"10","correct":true},{"latex":"12","correct":false},{"latex":"-10","correct":false},{"latex":"5","correct":false}]$json$::jsonb, $exp$Sustituye $x=2$: $4 - 14 + k = 0 \Rightarrow k = 10$.$exp$),
  ($id$cuad-h-05$id$, $sec$algebra$sec$, $sub$cuadratica$sub$, $law$cuadratica-formula-general$law$, $diff$hard$diff$, $prompt$La suma de las raíces de $2x^2 - 6x + 4 = 0$ es...$prompt$, $json$[{"latex":"3","correct":true},{"latex":"-3","correct":false},{"latex":"2","correct":false},{"latex":"6","correct":false}]$json$::jsonb, $exp$La suma de raíces es $-\frac{b}{a} = -\frac{-6}{2} = 3$.$exp$),
  ($id$divpol-f-01$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$easy$diff$, $prompt$Divide: $(x^2 + 3x + 2) \div (x + 1)$$prompt$, $json$[{"latex":"x + 2","correct":true},{"latex":"x + 1","correct":false},{"latex":"x - 2","correct":false},{"latex":"x^2 + 2","correct":false}]$json$::jsonb, $exp$$x^2 + 3x + 2 = (x+1)(x+2)$, así que al dividir entre $x+1$ queda $x+2$.$exp$),
  ($id$divpol-f-02$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$easy$diff$, $prompt$Divide: $(x^3 - x^2) \div x$$prompt$, $json$[{"latex":"x^2 - x","correct":true},{"latex":"x^2 + x","correct":false},{"latex":"x^3 - x","correct":false},{"latex":"x^2","correct":false}]$json$::jsonb, $exp$Divide cada término entre $x$: $\frac{x^3}{x} - \frac{x^2}{x} = x^2 - x$.$exp$),
  ($id$divpol-f-03$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$easy$diff$, $prompt$Divide: $(6x^2 + 3x) \div 3x$$prompt$, $json$[{"latex":"2x + 1","correct":true},{"latex":"2x - 1","correct":false},{"latex":"6x + 3","correct":false},{"latex":"2x","correct":false}]$json$::jsonb, $exp$$\frac{6x^2}{3x} + \frac{3x}{3x} = 2x + 1$.$exp$),
  ($id$divpol-f-04$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$easy$diff$, $prompt$Divide: $(x^2 - 9) \div (x - 3)$$prompt$, $json$[{"latex":"x + 3","correct":true},{"latex":"x - 3","correct":false},{"latex":"x + 9","correct":false},{"latex":"x^2 + 3","correct":false}]$json$::jsonb, $exp$$x^2 - 9 = (x-3)(x+3)$, así que al dividir entre $x-3$ queda $x+3$.$exp$),
  ($id$divpol-f-05$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$easy$diff$, $prompt$Divide: $(x^2 - 4x) \div x$$prompt$, $json$[{"latex":"x - 4","correct":true},{"latex":"x + 4","correct":false},{"latex":"x^2 - 4","correct":false},{"latex":"4 - x","correct":false}]$json$::jsonb, $exp$$\frac{x^2}{x} - \frac{4x}{x} = x - 4$.$exp$),
  ($id$divpol-m-01$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$medium$diff$, $prompt$Divide: $(x^2 + 5x + 6) \div (x + 2)$$prompt$, $json$[{"latex":"x + 3","correct":true},{"latex":"x + 2","correct":false},{"latex":"x - 3","correct":false},{"latex":"x^2 + 3","correct":false}]$json$::jsonb, $exp$$x^2 + 5x + 6 = (x+2)(x+3)$, así que el cociente es $x+3$.$exp$),
  ($id$divpol-m-02$id$, $sec$algebra$sec$, $sub$division-polinomios$sub$, $law$division-polinomios$law$, $diff$medium$diff$, $prompt$Divide: $(x^3 + 2x^2 + x) \div x$$prompt$, $json$[{"latex":"x^2 + 2x + 1","correct":true},{"latex":"x^2 + 2x","correct":false},{"latex":"x^3 + 2x + 1","correct":false},{"latex":"x^2 + x + 1","correct":false}]$json$::jsonb, $exp$Divide término a término: $x^2 + 2x + 1$.$exp$)
